<?php namespace App\Http\Controllers; use App\Models\{Sale,SaleItem,Product,StockMovement}; use App\Services\InventoryService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use RuntimeException;
class ReturnController extends Controller {public function index(){return view('returns.index');} public function store(Request $r,InventoryService $inv){$d=$r->validate(['invoice_no'=>'required','product_id'=>'required|exists:products,id','quantity'=>'required|numeric|min:.001']);return DB::transaction(function()use($d,$r,$inv){$sale=Sale::where('invoice_no',$d['invoice_no'])->firstOrFail();$item=SaleItem::where('sale_id',$sale->id)->where('product_id',$d['product_id'])->firstOrFail();if($d['quantity']>$item->quantity)throw new RuntimeException('Return quantity exceeds sold quantity.');$p=Product::lockForUpdate()->findOrFail($d['product_id']);$inv->change($p,$d['quantity'],'RETURN',Sale::class,$sale->id,$r->user()->id,'Sales return');return back()->with('success','Return processed and stock restored.');});}}
